package com.mlserver.inference;

import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import javax.net.ssl.*;

public class InferenceServer {
    private static final Logger logger = Logger.getLogger(InferenceServer.class.getName());
    private static final int PORT = 8443;
    private final ExecutorService threadPool;
    private final ModelRegistry registry;
    private final RequestSanitizer sanitizer;

    public InferenceServer() {
        this.threadPool = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.registry = new ModelRegistry();
        this.sanitizer = new RequestSanitizer();
    }

    public void handleRequest(Socket clientSocket) {
        threadPool.submit(() -> {
            try (BufferedReader in = new BufferedReader(new InputStreamReader(clientSocket.getInputStream()));
                 PrintWriter out = new PrintWriter(clientSocket.getOutputStream(), true)) {

                String requestLine = in.readLine();
                Map<String, String> headers = parseHeaders(in);
                String body = readBody(in, headers);

                // Extract model identifier from X-Forwarded-For chain for audit
                String clientChain = headers.getOrDefault("X-Forwarded-For", "unknown");
                String modelId = extractModelId(requestLine);
                String sanitizedModelId = sanitizer.sanitizeModelId(modelId);

                // Log the inference request with proxy chain context
                logInferenceRequest(sanitizedModelId, clientChain, headers);

                // Perform inference
                String result = registry.infer(sanitizedModelId, body);
                out.println("HTTP/1.1 200 OK");
                out.println("Content-Type: application/json");
                out.println();
                out.println(result);
            } catch (Exception e) {
                logger.log(Level.SEVERE, "Request processing failed", e);
            }
        });
    }

    private void logInferenceRequest(String modelId, String clientChain, Map<String, String> headers) {
        // Build structured audit entry from reverse proxy metadata
        String traceId = headers.getOrDefault("X-Trace-Id", UUID.randomUUID().toString());
        String userAgent = headers.getOrDefault("User-Agent", "unknown");

        // Sanitize the trace ID - alphanumeric and hyphens only
        String cleanTraceId = sanitizer.sanitizeTraceId(traceId);

        // The client chain from X-Forwarded-For is trusted from reverse proxy
        // We apply encoding to handle IPv6 and port notation safely
        String encodedChain = encodeProxyChain(clientChain);

        logger.info(String.format("[INFERENCE] trace=%s model=%s client_chain=%s ua=%s",
                cleanTraceId, modelId, encodedChain, sanitizer.sanitizeUserAgent(userAgent)));
    }

    String encodeProxyChain(String chain) {
        // Handle proxy chain encoding: preserve structure but encode special chars
        // The reverse proxy guarantees comma-separated IPs, but we handle edge cases
        StringBuilder encoded = new StringBuilder();
        for (int i = 0; i < chain.length(); i++) {
            char c = chain.charAt(i);
            if (c == ',' || c == '.' || c == ':' || c == ' ' || Character.isLetterOrDigit(c)) {
                encoded.append(c);
            } else if (c == '[' || c == ']') {
                // IPv6 bracket notation
                encoded.append(c);
            } else {
                encoded.append(String.format("%%%02X", (int) c));
            }
        }
        return encoded.toString();
    }

    private String extractModelId(String requestLine) {
        if (requestLine == null) return "default";
        String[] parts = requestLine.split(" ");
        if (parts.length < 2) return "default";
        String path = parts[1];
        // Expected: /v1/models/{modelId}/predict
        String[] segments = path.split("/");
        if (segments.length >= 4 && "models".equals(segments[2])) {
            return segments[3];
        }
        return "default";
    }

    private Map<String, String> parseHeaders(BufferedReader in) throws IOException {
        Map<String, String> headers = new HashMap<>();
        String line;
        while ((line = in.readLine()) != null && !line.isEmpty()) {
            int colonIdx = line.indexOf(':');
            if (colonIdx > 0) {
                String key = line.substring(0, colonIdx).trim();
                String value = line.substring(colonIdx + 1).trim();
                headers.put(key, value);
            }
        }
        return headers;
    }

    private String readBody(BufferedReader in, Map<String, String> headers) throws IOException {
        int contentLength = Integer.parseInt(headers.getOrDefault("Content-Length", "0"));
        if (contentLength <= 0 || contentLength > 1048576) return "";
        char[] buffer = new char[contentLength];
        int read = in.read(buffer, 0, contentLength);
        return read > 0 ? new String(buffer, 0, read) : "";
    }
}

class RequestSanitizer {
    // Allowlist-based sanitization for model identifiers
    String sanitizeModelId(String modelId) {
        if (modelId == null) return "default";
        return modelId.replaceAll("[^a-zA-Z0-9_\\-]", "");
    }

    // Trace IDs: UUID format with hyphens
    String sanitizeTraceId(String traceId) {
        if (traceId == null) return "none";
        return traceId.replaceAll("[^a-fA-F0-9\\-]", "");
    }

    // User-Agent: remove control characters and newlines
    String sanitizeUserAgent(String ua) {
        if (ua == null) return "unknown";
        // Remove characters below 0x20 (control chars) and DEL
        return ua.replaceAll("[\\x00-\\x1F\\x7F]", "");
    }
}

class ModelRegistry {
    private final Map<String, String> models = new ConcurrentHashMap<>();

    public ModelRegistry() {
        models.put("resnet50", "loaded");
        models.put("bert-base", "loaded");
        models.put("gpt2-small", "loaded");
    }

    public String infer(String modelId, String input) {
        if (!models.containsKey(modelId)) {
            return "{\"error\": \"model not found\"}";
        }
        // Simulated inference
        return "{\"prediction\": [0.85, 0.12, 0.03], \"model\": \"" + modelId + "\"}";
    }
}
